WITH valid_orders AS (SELECT member_id, order_id, ordered_at, paid_cents, refund_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), member_month AS (SELECT member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS valid_order_count, SUM(paid_cents - refund_cents) AS net_sales_cents FROM valid_orders GROUP BY member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE)) SELECT member_id, month_start, member_id || '|' || CAST(month_start AS VARCHAR) AS member_month_key, valid_order_count, net_sales_cents FROM member_month